<!doctype html><html lang="id" translate="no" class="notranslate"><head><meta charset="utf-8"><meta name="google" content="notranslate"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pendaftaran Online · <?=e(app_name())?></title><link rel="stylesheet" href="/assets/online-registration.css?v=<?=e((string)filemtime(__DIR__.'/../../public/assets/online-registration.css'))?>"></head><body><header><div class="brand">RQ</div><div><small>PENDAFTARAN ONLINE</small><h1><?=e(app_name())?></h1></div></header><main><section class="intro"><span>FORMULIR KUNJUNGAN</span><h2>Daftar sebelum datang</h2><p>Pilih layanan dan tanggal kunjungan. Nomor antrean aktif diberikan saat Anda check-in pada hari kunjungan.</p></section><?php if($error):?><div class="alert" role="alert"><?=e($error)?></div><?php endif?><form method="post" class="form-card"><input type="hidden" name="_csrf" value="<?=csrf_token()?>"><div class="grid"><label>Layanan<select name="service_id" required><option value="">Pilih layanan</option><?php foreach($services as $service):?><option value="<?=e($service['id'])?>" <?=($_POST['service_id']??'')==$service['id']?'selected':''?>><?=e($service['name'])?></option><?php endforeach?></select></label><label>Tanggal kunjungan<input type="date" name="visit_date" min="<?=date('Y-m-d')?>" max="<?=(new DateTimeImmutable('+90 days'))->format('Y-m-d')?>" value="<?=e($_POST['visit_date']??date('Y-m-d'))?>" required></label><label>Nama lengkap<input name="visitor_name" minlength="2" maxlength="120" value="<?=e($_POST['visitor_name']??'')?>" autocomplete="name" required></label><label>Nomor telepon<input name="phone" maxlength="30" value="<?=e($_POST['phone']??'')?>" autocomplete="tel" inputmode="tel"></label><label>Email <small>(opsional)</small><input type="email" name="email" maxlength="190" value="<?=e($_POST['email']??'')?>" autocomplete="email"></label><label>Nomor identitas <small>(opsional)</small><input name="identity_number" maxlength="80" value="<?=e($_POST['identity_number']??'')?>"></label></div><label>Keperluan atau catatan <small>(opsional)</small><textarea name="notes" maxlength="2000" rows="3"><?=e($_POST['notes']??'')?></textarea></label><label class="consent"><input type="checkbox" name="consent" value="1" required> Saya menyetujui data ini digunakan untuk pendaftaran dan pelayanan antrean.</label><button type="submit">Kirim pendaftaran</button></form><p class="checkin-link">Sudah mendaftar? <a href="/online-check-in">Check-in dengan kode pendaftaran</a></p></main><footer>Created by Sulis Setiyawan — rekakarsa</footer></body></html>
